async (page) => {
  await page.evaluate(() => {
    window.__errs = [];
    window.addEventListener('error', e => window.__errs.push(['exception', e.message]));
    window.addEventListener('unhandledrejection', e => window.__errs.push(['promise-rejection', String(e.reason)]));
  });
  const btns = await page.locator('button').all();
  const out = [];
  for (const b of btns) {
    const sec = await b.evaluate(el => { const s = el.closest('section,[id],div'); return (s && (s.id || s.querySelector('h1,h2,h3')?.textContent)) + ' | ' + el.textContent; });
    await page.evaluate(() => window.__errs = []);
    await b.click();
    await page.waitForTimeout(1500);
    out.push([sec, await page.evaluate(() => window.__errs)]);
  }
  return out;
}

